        /// <summary>Parkour + locomotion, for the probe.</summary>
        public static readonly string[] Everything = Concat(All, LocomotionClips);
        static string[] Concat(string[] a, string[] b) { var r = new string[a.Length + b.Length]; a.CopyTo(r, 0); b.CopyTo(r, a.Length); return r; }

        static readonly Dictionary<string, AnimationClip> _cache = new Dictionary<string, AnimationClip>();

        /// <summary>The one real AnimationClip in an imported FBX (one take per
        /// file, named after the file) or the .anim itself. Null if missing;
        /// every caller is null-safe.</summary>
        public static AnimationClip Get(string assetPath)
        {
            if (string.IsNullOrEmpty(assetPath)) return null;
            if (_cache.TryGetValue(assetPath, out var hit) && hit != null) return hit;
            AnimationClip clip = null;
            if (assetPath.EndsWith(".anim"))
                clip = ArtAssets.Load<AnimationClip>(assetPath);
            else
            {
                var clips = ArtAssets.LoadAllAt<AnimationClip>(assetPath);
                foreach (var c in clips) { if (c == null) continue; if (c.name.StartsWith("__preview")) continue; clip = c; break; }
            }
            _cache[assetPath] = clip;
            return clip;
        }

        public static AvatarMask GetMask(string name)
        {
            return ArtAssets.Load<AvatarMask>(MaskRoot + "/" + name + ".mask");
        }

        /// <summary>The file stem a clip was loaded from (clip.name equals the
        /// take name, which the pack names after the file).</summary>
        public static string Stem(string assetPath)
        {
            int i = assetPath.LastIndexOf('/'); string f = i >= 0 ? assetPath.Substring(i + 1) : assetPath;
            int d = f.LastIndexOf('.'); return d > 0 ? f.Substring(0, d) : f;
        }
